  "implementation": "def solve(case):
    if not isinstance(case, dict) or 'segments' not in case or 'budget' not in case:
        raise ValueError("Invalid case structure")
    segments = case['segments']
    budget = case['budget']
    if not isinstance(segments, list) or not isinstance(budget, int):
        raise ValueError("Invalid types")
    for s in segments:
        if not all(k in s for k in ('name','importance','minimum','capacity')):
            raise ValueError("Segment missing keys")
        if not all(isinstance(s[k], int) for k in ('importance','minimum','capacity')):
            raise ValueError("Segment field not int")
        if not isinstance(s['name'], str):
            raise ValueError("Segment name not string")
        if s['minimum'] < 0 or s['capacity'] < s['minimum']:
            raise ValueError("Segment bounds invalid")
    min_sum = sum(s['minimum'] for s in segments)
    cap_sum = sum(s['capacity'] for s in segments)
    if not (min_sum <= budget <= cap_sum):
        raise ValueError("Budget out of feasible range")
    allocations = [s['minimum'] for s in segments]
    remaining = budget - min_sum
    from fractions import Fraction
    while remaining > 0:
        best_idx = None
        best_key = None
        for i, seg in enumerate(segments):
            if allocations[i] < seg['capacity']:
                key = (Fraction(seg['importance'], allocations[i] + 1), -i)
                if best_idx is None or key > best_key:
                    best_key = key
                    best_idx = i
        if best_idx is None:
            raise ValueError("Cannot allocate; check constraints")
        allocations[best_idx] += 1
        remaining -= 1
    total = budget
    by_name = {seg['name']: allocations[i] for i, seg in enumerate(segments)}
    return {"allocations": allocations, "by_name": by_name, "total": total}"
}
